<?php
declare(strict_types=1);
$config=require dirname(__DIR__).'/config/app.php';require dirname(__DIR__).'/app/Core/Security.php';require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Core/SchemaInspector.php';require dirname(__DIR__).'/app/Core/WorkflowHelpers.php';require dirname(__DIR__).'/app/Core/AuditLogger.php';require dirname(__DIR__).'/app/Services/Authorization.php';Security::startSession($config);
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}if(!Security::verifyCsrf($_POST['_csrf']??null)){http_response_code(419);exit('Session expired.');}
try{$db=Database::connection();$user=WorkflowHelpers::requireUser($db,$config);$type=(string)($_POST['request_type']??'');$details=WorkflowHelpers::clean((string)($_POST['details']??''),3000);$allowed=['ACCESS','CORRECTION','ERASURE','OBJECTION','PORTABILITY','OTHER'];if(!in_array($type,$allowed,true)||$details==='')throw new InvalidArgumentException('Choose a request type and describe your request.');$q=$db->prepare("INSERT INTO data_subject_requests (user_id,request_type,details,status) VALUES (:uid,:type,:details,'SUBMITTED')");$q->execute(['uid'=>$user['user_id'],'type'=>$type,'details'=>$details]);$id=(int)$db->lastInsertId();AuditLogger::record($db,(int)$user['user_id'],'DATA_SUBJECT_REQUEST_SUBMITTED','data_subject_request',$id,['request_type'=>$type]);header('Location: privacy.php?submitted=1');exit;}catch(InvalidArgumentException $e){http_response_code(422);$msg=$e->getMessage();}catch(Throwable $e){error_log('Data subject request: '.$e->getMessage());http_response_code(503);$msg='Unable to submit your privacy request.';}
require dirname(__DIR__).'/app/Core/PublicPage.php';pageHeader('Privacy request not submitted');?><main id="main-content" class="section"><div class="notice warning"><?= Security::e($msg??'Request failed.') ?></div><a href="privacy.php" class="action-secondary">Return to privacy notice</a></main><?php pageFooter();
